const memory=new Map();
async function database(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Photo storage unavailable'));return;}const req=indexedDB.open('mallside-portraits',1);req.onupgradeneeded=()=>req.result.createObjectStore('images');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
export async function storePortrait(key,data){memory.set(key,data);let db;try{db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(data,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});return true;}catch{return false;}finally{db?.close();}}
export async function loadPortrait(key){if(memory.has(key))return memory.get(key);let db;try{db=await database();const data=await new Promise((resolve,reject)=>{const req=db.transaction('images').objectStore('images').get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});if(data)memory.set(key,data);return data;}catch{return null;}finally{db?.close();}}
export async function deletePortrait(key){memory.delete(key);let db;try{db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch{}finally{db?.close();}}
